/**
 * Core domain model and stable identifiers
 * Deterministic, dependency-free foundation module (generated baseline — hand-polish deepens domain logic).
 * @typedef {{ id: string, occurredAt: string, quantity: number, attributes?: Record<string, string> }} DomainInput
 * @typedef {{ code: string, severity: "info" | "warning" | "critical", evidence: string[] }} DomainFinding
 * @typedef {{ subjectId: string, status: "accepted" | "blocked", findings: DomainFinding[] }} DomainResult
 */

/**
 * Evaluate one input against the core domain model and stable identifiers policy.
 * @param {DomainInput} input
 * @returns {DomainResult}
 */
export function evaluateDomain(input) {
	const findings = [];
	if (!input || typeof input.id !== "string" || input.id.length === 0) {
		return { subjectId: "unknown", status: "blocked", findings: [{ code: "domain/missing-id", severity: "critical", evidence: ["input.id is required"] }] };
	}
	if (!Number.isFinite(input.quantity) || input.quantity < 0) {
		findings.push({ code: "domain/quantity-range", severity: "critical", evidence: [`quantity ${input.quantity} is outside [0, ∞)`] });
	}
	if (!/^\d{4}-\d{2}-\d{2}T/.test(input.occurredAt ?? "")) {
		findings.push({ code: "domain/timestamp-shape", severity: "warning", evidence: [`occurredAt ${String(input.occurredAt)} is not ISO-8601`] });
	}
	const blocked = findings.some((finding) => finding.severity === "critical");
	if (findings.length === 0) {
		findings.push({ code: "domain/clean", severity: "info", evidence: ["all deterministic checks passed"] });
	}
	return { subjectId: input.id, status: blocked ? "blocked" : "accepted", findings };
}

